List<List<Integer>> nested = List.of(List.of(1, 2), List.of(3, 4));
nested.stream()
      .flatMap(List::stream)
      .map(n -> n * 2)
      .forEach(System.out::print);

Stream.of("apple", "pear", "banana")
      .filter(s -> {
          System.out.print("F:" + s + " ");
          return s.length() == 4;
      })
      .map(s -> {
          System.out.print("M:" + s + " ");
          return s.toUpperCase();
      })
      .findFirst();
